gHe(){return"\u0647\u0627\u0648\u067e\u06ce\u0686"},
ga2V(){return"\u06a9\u0627\u062a\u0627\u0644\u06c6\u06af"},
ga2Q(){return"\u062c\u06c6\u0631\u06d5\u06a9\u0627\u0646\u06cc \u06a9\u06d5\u06cc\u0633\u060c \u0642\u06c6\u0646\u0627\u063a\u06d5\u06a9\u0627\u0646 \u0648 \u0645\u0627\u062f\u062f\u06d5\u06a9\u0627\u0646 \u2014 \u06af\u06c6\u0695\u0627\u0646\u06a9\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u0627\u0646 \u062f\u06d5\u0633\u062a\u0628\u06d5\u062c\u06ce \u0644\u06d5 \u0647\u06d5\u0645\u0648\u0648 \u0634\u0648\u06ce\u0646\u06ce\u06a9 \u062c\u06ce\u0628\u06d5\u062c\u06ce \u062f\u06d5\u0628\u0646."},
ga2P(){return"\u0642\u06c6\u0646\u0627\u063a\u06d5\u06a9\u0627\u0646"},
gHL(){return"\u0632\u06cc\u0627\u062f\u06a9\u0631\u062f\u0646\u06cc \u0642\u06c6\u0646\u0627\u063a"},
ga1K(){return"\u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc\u06a9\u0631\u062f\u0646\u06cc \u0642\u06c6\u0646\u0627\u063a"},
ga0Z(){return"\u0626\u06d5\u0631\u0634\u06cc\u0641\u06a9\u0631\u062f\u0646"},
ga1C(){return"\u0633\u0695\u06cc\u0646\u06d5\u0648\u06d5\u06cc \u0647\u06d5\u0645\u06cc\u0634\u06d5\u06cc\u06cc"},
ga2D(){return"\u06af\u06d5\u0695\u0627\u0646\u062f\u0646\u06d5\u0648\u06d5"},
ga12(){return"\u0626\u06d5\u0631\u0634\u06cc\u0641\u06a9\u0631\u0627\u0648"},
ga11(){return"\u0626\u06d5\u0645 \u0642\u06c6\u0646\u0627\u063a\u06d5 \u0626\u06d5\u0631\u0634\u06cc\u0641 \u0628\u06a9\u0631\u06ce\u062a\u061f"},
a10(a){return"\xab"+a+"\xbb \u0644\u06d5 \u0647\u06ce\u06b5\u06cc \u0647\u06d5\u0645\u0648\u0648 \u062c\u06c6\u0631\u06d5 \u06a9\u06d5\u06cc\u0633\u06ce\u06a9 \u0648 \u0644\u06d5 \u062a\u06d5\u062e\u062a\u06d5\u06a9\u06d5 \u0644\u0627\u062f\u06d5\u0628\u0631\u062f\u0631\u06ce\u062a. \u06a9\u06d5\u06cc\u0633\u06d5 \u06a9\u06c6\u0646\u06d5\u06a9\u0627\u0646 \u0648 \u0645\u06ce\u0698\u0648\u0648 \u0646\u0627\u0648\u06d5\u06a9\u06d5 \u062f\u06d5\u0647\u06ce\u06b5\u0646\u06d5\u0648\u06d5. \u062f\u0648\u0627\u062a\u0631 \u062f\u06d5\u062a\u0648\u0627\u0646\u06cc\u062a \u0628\u06cc\u06af\u06d5\u0695\u06ce\u0646\u06cc\u062a\u06d5\u0648\u06d5."},
